from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path
MODULE="alliance_acquisition_intent_closure_v425.py"
REG="alliance_optional_property_modules.py"
DATA=""
def chk(p): compile(p.read_text(encoding="utf-8"),str(p),"exec")
def main():
 r=Path.cwd()
 req=["alliance_automation_grammar_rescue_v423.py","alliance_automation_closure_v422.py","alliance_automation_truth_escalator_v421.py","alliance_automation_machine_v420.py","alliance_cre_championship_v410.py","alliance_cre_academy_v402.py",REG]
 miss=[x for x in req if not (r/x).exists()]
 if miss: raise SystemExit("Missing cumulative files: "+", ".join(miss))
 reg=r/REG; old=reg.read_text(encoding="utf-8")
 bak=r/f"{REG}.before-v425-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"; shutil.copy2(reg,bak)
 (r/MODULE).write_text(base64.b64decode(DATA).decode(),encoding="utf-8")
 marker="# FOUNDATION 4.2.5 - Alliance Acquisition Intent Closure"
 if marker not in old:
  pos=old.rfind("    return result")
  if pos<0: raise SystemExit("Registrar return not found; no changes made.")
  block=r"""
    # FOUNDATION 4.2.5 - Alliance Acquisition Intent Closure
    # Additive only. Two independent generic acquisition-intent judges for final V4 abstentions.
    try:
        if _route_exists(app, "/api/property-brain/automation-v425/status"):
            result["automation_v425"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/automation-v425","error":None}
        else:
            import alliance_acquisition_intent_closure_v425 as automation_v425
            result["automation_v425"] = {**automation_v425.register(core), "error": None}
    except Exception as exc:
        result["automation_v425"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/automation-v425","fail_safe":True}

"""
  reg.write_text(old[:pos]+block+old[pos:],encoding="utf-8")
 chk(r/MODULE); chk(reg)
 txt=reg.read_text(encoding="utf-8")
 checks={"v402":"academy_v402" in txt,"v410":"championship_v410" in txt,"v420":"automation_v420" in txt,"v421":"automation_v421" in txt,"v422":"automation_v422" in txt,"v423":"automation_v423" in txt,"v425":"automation_v425" in txt}
 if not all(checks.values()): raise SystemExit("Cumulative verification failed: "+repr(checks))
 print("Alliance Acquisition Intent Closure 4.2.5 installed")
 print("Fixes generic plural asset + wants-to-purchase demand grammar")
 print("Requires two independent judges to agree")
 print("Frozen V4 student unchanged")
 print("Production/WhatsApp/Gold writes: 0")
 print("Dashboard: /property-brain/automation-v425")
 print("Backup:",bak)
if __name__=="__main__": main()
